CREATE TABLE IF NOT EXISTS p10_channel_chats (id BIGINT AUTO_INCREMENT PRIMARY KEY, sender_id BIGINT NOT NULL, chat_type INT NOT NULL, scene VARCHAR(64) NOT NULL, line INT NOT NULL, content VARCHAR(160) NOT NULL, created_at BIGINT NOT NULL, sender_info LONGBLOB NOT NULL, KEY idx_p10_channel_sender(sender_id), KEY idx_p10_channel_scope(chat_type,scene,line)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
